std::vector<char> read(std::string p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f){fprintf(stderr,"missing %s\n",p.c_str());exit(3);} auto n=f.tellg();f.seekg(0);std::vector<char>b(n);f.read(b.data(),n);return b;}
int main(int argc,char**argv){if(argc!=7){fprintf(stderr,"replay shader entry inputdir x y z\n");return 1;}auto code=read(argv[1]);std::string dir=argv[3]; VkInstance instance;VkApplicationInfo app{VK_STRUCTURE_TYPE_APPLICATION_INFO};app.apiVersion=VK_API_VERSION_1_2;VkInstanceCreateInfo ici{VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO};ici.pApplicationInfo=&app;VK(vkCreateInstance(&ici,0,&instance));uint32_t count=0;VK(vkEnumeratePhysicalDevices(instance,&count,0));if(!count)return 4;std::vector<VkPhysicalDevice> phys(count);VK(vkEnumeratePhysicalDevices(instance,&count,phys.data()));auto gpu=phys[0];VkPhysicalDeviceProperties props;vkGetPhysicalDeviceProperties(gpu,&props);fprintf(stderr,"device=%s\n",props.deviceName);uint32_t nq=0;vkGetPhysicalDeviceQueueFamilyProperties(gpu,&nq,0);std::vector<VkQueueFamilyProperties>qs(nq);vkGetPhysicalDeviceQueueFamilyProperties(gpu,&nq,qs.data());uint32_t family=0;for(;family<nq;family++)if(qs[family].queueFlags&VK_QUEUE_COMPUTE_BIT)break;float priority=1;VkDeviceQueueCreateInfo qi{VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO};qi.queueFamilyIndex=family;qi.queueCount=1;qi.pQueuePriorities=&priority;VkDeviceCreateInfo di{VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO};di.queueCreateInfoCount=1;di.pQueueCreateInfos=&qi;VkDevice dev;VK(vkCreateDevice(gpu,&di,0,&dev));VkQueue queue;vkGetDeviceQueue(dev,family,0,&queue);VkPhysicalDeviceMemoryProperties mem;vkGetPhysicalDeviceMemoryProperties(gpu,&mem);
VkBuffer bufs[7];VkDeviceMemory allocs[7];void*ptrs[7];VkDescriptorBufferInfo bis[7];VkDescriptorSetLayoutBinding bindings[7];size_t sizes[7];
for(int i=0;i<7;i++){auto data=read(dir+"/b"+std::to_string(i)+".bin");sizes[i]=data.size();if(!sizes[i])return 5;VkBufferCreateInfo bi{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};bi.size=sizes[i]+256;bi.usage=i==6?VK_BUFFER_USAGE_UNIFORM_BUFFER_BIT:VK_BUFFER_USAGE_STORAGE_BUFFER_BIT;bi.sharingMode=VK_SHARING_MODE_EXCLUSIVE;VK(vkCreateBuffer(dev,&bi,0,&bufs[i]));VkMemoryRequirements mr;vkGetBufferMemoryRequirements(dev,bufs[i],&mr);uint32_t mt=0;for(;mt<mem.memoryTypeCount;mt++)if((mr.memoryTypeBits&(1u<<mt))&&(mem.memoryTypes[mt].propertyFlags&(VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT|VK_MEMORY_PROPERTY_HOST_COHERENT_BIT))==(VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT|VK_MEMORY_PROPERTY_HOST_COHERENT_BIT))break;if(mt==mem.memoryTypeCount)return 6;VkMemoryAllocateInfo ai{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};ai.allocationSize=mr.size;ai.memoryTypeIndex=mt;VK(vkAllocateMemory(dev,&ai,0,&allocs[i]));VK(vkBindBufferMemory(dev,bufs[i],allocs[i],0));VK(vkMapMemory(dev,allocs[i],0,mr.size,0,&ptrs[i]));memcpy(ptrs[i],data.data(),sizes[i]);memset((char*)ptrs[i]+sizes[i],0xa5,256);bis[i]={bufs[i],0,sizes[i]};bindings[i]={(uint32_t)i,i==6?VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER:VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,1,VK_SHADER_STAGE_COMPUTE_BIT,0};}
VkDescriptorSetLayoutCreateInfo li{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};li.bindingCount=7;li.pBindings=bindings;VkDescriptorSetLayout layout;VK(vkCreateDescriptorSetLayout(dev,&li,0,&layout));VkDescriptorPoolSize ps[2]={{VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,6},{VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER,1}};VkDescriptorPoolCreateInfo pi{VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO};pi.maxSets=1;pi.poolSizeCount=2;pi.pPoolSizes=ps;VkDescriptorPool pool;VK(vkCreateDescriptorPool(dev,&pi,0,&pool));VkDescriptorSetAllocateInfo si{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO};si.descriptorPool=pool;si.descriptorSetCount=1;si.pSetLayouts=&layout;VkDescriptorSet set;VK(vkAllocateDescriptorSets(dev,&si,&set));VkWriteDescriptorSet ws[7]{};for(int i=0;i<7;i++){ws[i].sType=VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;ws[i].dstSet=set;ws[i].dstBinding=i;ws[i].descriptorCount=1;ws[i].descriptorType=bindings[i].descriptorType;ws[i].pBufferInfo=&bis[i];}vkUpdateDescriptorSets(dev,7,ws,0,0);
VkPipelineLayoutCreateInfo pli{VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};pli.setLayoutCount=1;pli.pSetLayouts=&layout;VkPipelineLayout pl;VK(vkCreatePipelineLayout(dev,&pli,0,&pl));VkShaderModuleCreateInfo smi{VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};smi.codeSize=code.size();smi.pCode=(uint32_t*)code.data();VkShaderModule sm;VK(vkCreateShaderModule(dev,&smi,0,&sm));VkComputePipelineCreateInfo ci{VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO};ci.layout=pl;ci.stage.sType=VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;ci.stage.stage=VK_SHADER_STAGE_COMPUTE_BIT;ci.stage.module=sm;ci.stage.pName=argv[2];VkPipeline pipeline;fprintf(stderr,"creating compute pipeline\n");VK(vkCreateComputePipelines(dev,VK_NULL_HANDLE,1,&ci,0,&pipeline));fprintf(stderr,"pipeline ready\n");VkCommandPoolCreateInfo cpi{VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO};cpi.queueFamilyIndex=family;VkCommandPool cp;VK(vkCreateCommandPool(dev,&cpi,0,&cp));VkCommandBufferAllocateInfo cai{VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};cai.commandPool=cp;cai.level=VK_COMMAND_BUFFER_LEVEL_PRIMARY;cai.commandBufferCount=1;VkCommandBuffer cmd;VK(vkAllocateCommandBuffers(dev,&cai,&cmd));VkCommandBufferBeginInfo cbi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};VK(vkBeginCommandBuffer(cmd,&cbi));vkCmdBindPipeline(cmd,VK_PIPELINE_BIND_POINT_COMPUTE,pipeline);vkCmdBindDescriptorSets(cmd,VK_PIPELINE_BIND_POINT_COMPUTE,pl,0,1,&set,0,0);vkCmdDispatch(cmd,atoi(argv[4]),atoi(argv[5]),atoi(argv[6]));VkMemoryBarrier barrier{VK_STRUCTURE_TYPE_MEMORY_BARRIER};barrier.srcAccessMask=VK_ACCESS_SHADER_WRITE_BIT;barrier.dstAccessMask=VK_ACCESS_HOST_READ_BIT;vkCmdPipelineBarrier(cmd,VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,VK_PIPELINE_STAGE_HOST_BIT,0,1,&barrier,0,0,0,0);VK(vkEndCommandBuffer(cmd));VkSubmitInfo submit{VK_STRUCTURE_TYPE_SUBMIT_INFO};submit.commandBufferCount=1;submit.pCommandBuffers=&cmd;fprintf(stderr,"submitting compute\n");VK(vkQueueSubmit(queue,1,&submit,VK_NULL_HANDLE));VK(vkQueueWaitIdle(queue));for(int i=0;i<7;i++){for(size_t j=0;j<256;j++)if(((unsigned char*)ptrs[i])[sizes[i]+j]!=0xa5){fprintf(stderr,"CANARY CORRUPTION buffer%d offset%zu\n",i,j);return 7;} std::ofstream f(dir+"/out"+std::to_string(i)+".bin",std::ios::binary);f.write((char*)ptrs[i],sizes[i]);}fprintf(stderr,"all seven allocation-end canaries intact\ndispatch complete\n");vkDestroyDevice(dev,0);vkDestroyInstance(instance,0);}
